function ddOff(){
try{
  var box=D.querySelector(".js-price-container"); if(!box) return;
  var pay=box.querySelector(".js-payment-discount-price-product-container"); if(!pay) return;
  var pd=box.querySelector(".js-price-display"), pp=box.querySelector(".js-payment-discount-price-product");
  var tag=pay.querySelector(".dd-off");
  /* se calcula sobre los precios que se ven, no sobre los data- : al cambiar de variante
     el atributo del precio por transferencia queda viejo y daba porcentajes falsos */
  function num(el){ if(!el) return 0; var s=(el.textContent||"").replace(/[^0-9.,]/g,""); if(!s) return 0;
    s=s.replace(/\./g,"").replace(",","."); var n=parseFloat(s); return isNaN(n)?0:n; }
  var a=num(pd), b=num(pp);
  var p=(a>0&&b>0&&b<a)?Math.round((1-b/a)*100):0;
  if(p>=1&&p<=90){
    var txt=p+"% OFF";
    if(!tag){ tag=D.createElement("span"); tag.className="dd-off"; pay.insertBefore(tag,pay.firstChild); }
    if(tag.textContent!==txt) tag.textContent=txt;
  } else if(tag && tag.parentNode){ tag.parentNode.removeChild(tag); }
}catch(e){}
}
