function ddClean2(t){ return t.split('-').map(function(seg){ var toks=seg.trim().split(/\s+/).filter(Boolean); var out=[],buf=[];
function flush(){ if(buf.length>=3){ out.push(buf.join('')); } else { for(var i=0;i<buf.length;i++) out.push(buf[i]); } buf=[]; }
toks.forEach(function(x){ if(x.length===1){ buf.push(x); } else { flush(); out.push(x); } }); flush(); return out.join(' '); }).filter(function(x){ return x.length; }).join(' '); }
function ddNames(){
try{
var els=Array.prototype.slice.call(D.querySelectorAll('h1, .modal-nav-hamburger a, .js-modal a, .js-modal .nav-list-link, .breadcrumbs .crumb, .page-header h2, .category-title'));
function ddSpaced(s){ var tk=s.trim().split(/\s+/); var run=0,mx=0; for(var k=0;k<tk.length;k++){ if(tk[k].length===1){ run++; if(run>mx) mx=run; } else { run=0; } } return mx>=3; }
els.forEach(function(e){
if(e.getAttribute('data-ddn')) return;
e.setAttribute('data-ddn','1');
var nodes=[]; var tw=D.createTreeWalker(e, NodeFilter.SHOW_TEXT, null, false); var nn; while((nn=tw.nextNode())){ nodes.push(nn); }
for(var i=0;i<nodes.length;i++){
var nd=nodes[i]; if(nd.nodeType!==3) continue;
var raw=nd.nodeValue; var tr=raw.trim();
if(!tr || tr.length>90) continue;
if(!ddSpaced(tr)) continue;
var c=ddClean2(tr);
if(c && c!==tr){ nd.nodeValue=raw.replace(tr,c); }
}
});
}catch(e){}
}
